#!/usr/bin/env python3
import json

def a(href, text):
    return '<a href="%s" target="_blank" rel="noopener">%s</a>' % (href, text)
def p(html): return {'t': 'p', 'html': html}

S1   = 'https://www.sec.gov/Archives/edgar/data/2130357/000162828026072484/anthropicpbc-sx1ax2.htm'
ROAD = 'https://www.anthropic.com/news/roadshow-launch'
TC   = 'https://techcrunch.com/2026/11/10/anthropic-sets-ipo-price-range-of-70-to-78-per-share-to-reach-an-implied-valuation-of-1-404-trillion/'
CNBC = 'https://www.cnbc.com/2026/11/15/anthropic-ipo-is-make-or-break-for-the-technology-industry.html'
STKA = 'https://stockanalysis.com/news/anthropic-founders-stakes-18-billion-ipo/'

lr = {
 'title': 'The lab that left to be careful',
 'fact': "A Slow Burn long read, Monday 16 November 2026. On Wednesday Anthropic is set to price the largest public offering an AI lab has ever attempted: 825 million shares at 70 to 78 dollars, a raise of up to 64.4 billion, a valuation the market may set near 1.4 trillion. The company selling those shares is nearly six years old, was founded by seven people who walked out of the sector's most famous lab in the same winter, and is governed by a trust that can fire its board. Its own prospectus supplies almost every number in this read - the revenue that went from 41 million dollars to 33 billion in under four years, the losses that ran ahead of it, and the 900 billion dollars of compute it has promised to buy. This is the build story: the exit, the constitution, the customers, the money, the burn, the guardrails, and the pricing room.",
 'groups': []
}
G = lr['groups']

G.append({'heading': '1. The exit', 'blocks': [
 p(' Anthropic was incorporated in Delaware in January 2021 - a public benefit corporation from its first day, not a conversion. Its seven co-founders arrived from the same address. Dario Amodei had spent four and a half years at OpenAI, leaving as Vice President of Research in December 2020; his sister Daniela, now Anthropic\'s president and chair of its board, left too. So did Tom Brown, who had led the engineering of GPT-3 and, with Dario Amodei, co-invented deep reinforcement learning from human feedback - the technique that turned base models into conversational assistants. So did Jack Clark, OpenAI\'s policy director and before that a technology journalist; Jared Kaplan, a Johns Hopkins physicist and one of the principal authors of the neural scaling laws; Sam McCandlish, who built and led OpenAI\'s scaling team; and Chris Olah, who led its interpretability research. Every one of those biographies is stated in the company\'s own prospectus (' + a(S1, 'the S-1') + ').'),
 p(' What they built first was not a product but a position. The prospectus describes the company as "first and foremost a research lab," founded on the belief that the most transformative technology in human history demands an extraordinary level of responsibility in its development. Its formal mission, written into the charter of a public benefit corporation, is the responsible development and maintenance of advanced AI for the long-term benefit of humanity. Read the founding as a bet on sequence: that the lab which made safety its structure - not its slogan - would attract the researchers, the customers and eventually the capital to matter. Nearly six years later the sequence is about to be priced.'),
]})

G.append({'heading': '2. The constitution', 'blocks': [
 p(' The company\'s signature training method is literally called Constitutional AI. Claude is trained against a written set of principles - the filing calls it Claude\'s constitution - currently organized around four priorities: being broadly safe, broadly ethical, compliant with the company\'s guidelines, and genuinely helpful. Under the method, the model evaluates, critiques and revises its own responses against those principles, so the document, not just human labelers, does the steering (' + a(S1, 'the prospectus definition') + '). It is the founders\' old research program turned into an operating system: RLHF made models listen to people; Constitutional AI makes them answer to a text.'),
 p(' The same instinct - publish the plumbing - shows up in the company\'s standards work. In November 2024 Anthropic introduced the Model Context Protocol, an open interface for connecting AI tools to enterprise data sources and workflows, and in December 2025 it donated MCP to the Linux Foundation\'s Agentic AI Foundation rather than keep it as a moat. Olah\'s interpretability group, the field\'s most cited effort to read what a model is actually doing internally, has been publishing throughout. The strategy is coherent enough to state plainly: make the safety research good enough that serious customers treat it as a feature, then make the connecting tissue open enough that the industry builds on it whether or not it buys from you.'),
]})

G.append({'heading': '3. The business that found them', 'blocks': [
 p(' The revenue ramp is the steepest the filing cabinet has seen. Anthropic booked 41 million dollars in 2023, 386 million in 2024, 4.6 billion in 2025 - and 33.2 billion in the first nine months of 2026 alone, a further rise of roughly twelve times over the same nine months of 2025 (' + a(S1, 'the S-1\'s own table') + '). The customer base underneath it: roughly 40 million customers on a trailing basis, more than 1,900 of them paying at a rate above one million dollars a year, and about 250 above ten million. Remaining performance obligations stood at 13.8 billion dollars at the end of September, with about three-quarters of that expected to convert to revenue within twelve months.'),
 p(' The product carrying the enterprise story is Claude Code, the coding agent the filing calls the clearest manifestation of what Anthropic means by "virtual collaborators" - the model does not just suggest the next line, it takes on the work. The company\'s stated aim is to extend that pattern from software developers to knowledge workers generally, a population it estimates will exceed one billion by 2028. Whatever one makes of the estimate, the order of events is unusual in this industry: the safety lab built the tool engineers pay for, and the tool is now the front door of a trillion-dollar offering.'),
]})

G.append({'heading': '4. The money', 'blocks': [
 p(' Capital arrived the way compute did: through the suppliers. Google signed note purchase agreements in September 2023 and August 2024, both since converted to preferred stock, and added a new facility in March 2026. Amazon invested 5 billion dollars in the Series H round in May 2026, under a note agreement that still has 15 billion available. In April 2026 the relationship was formalized into something larger and stranger: Anthropic committed to spend at least 110 billion dollars with Amazon over the ten years from May 2026 - a non-cancelable commitment with a true-up if it falls short (' + a(S1, 'the agreements section') + '). The cloud provider is simultaneously the investor, the landlord and the meter reader.'),
 p(' The offering itself repeats the pattern. Alongside the public float, AMD, Broadcom, Google, Micron, Microsoft, Nvidia and TSMC have agreed, severally, to buy 26 billion dollars of stock in a concurrent private placement at the IPO price, closing immediately after the offering (' + a(S1, 'the private placement terms') + '). The companies that will sell Anthropic its chips and its cloud are buying a piece of the buyer. It is the cleanest possible statement of what the AI build-out has become: a closed loop of suppliers financing the demand for their own supply.'),
]})

G.append({'heading': '5. The burn', 'blocks': [
 p(' The losses are as large as the revenues are fast. Anthropic lost 41.97 billion dollars in 2025 and 104.0 billion in the first nine months of 2026. Both numbers need the filing\'s own caveat: they are inflated by fair-value marks on convertible notes, and on a pro forma basis the losses are 32.4 billion and 96.8 billion - still, by any measure, the most expensive growth story ever brought to market. The company says it expects operating losses to continue (' + a(S1, 'the prospectus') + ').'),
 p(' The reason sits in one table: purchase commitments. Anthropic has committed roughly 900.9 billion dollars - substantially all of it for compute and infrastructure - with about 451.6 billion due before the end of 2030 and 70.7 billion due within twelve months of September 30, 2026. A further 150 to 175 billion of estimated payments under arrangements without fixed dollar commitments does not even appear in that table - of which an estimated 125 to 150 billion is additional Google TPU compute, for delivery between 2028 and 2031. The bet the founders are making is arithmetic, not mystical: that 33 billion of nine-month revenue is the base of a curve steep enough to service a trillion dollars of obligations. This week the public market decides whether it wants to hold the other side of that arithmetic.'),
]})

G.append({'heading': '6. The guardrails on paper', 'blocks': [
 p(' The structure buyers are being asked to accept is unlike anything on the exchange. Anthropic is a Delaware public benefit corporation. A Long-Term Benefit Trust - not the shareholders - elects and can remove a majority of the board. The seven co-founders, through a single Class F share held by their Founder LLC, control 50.1% of the aggregate vote, and 61.3% of total voting power after the offering. A separate Anthropic Public Benefit Fund holds 846,840,960 Class N shares - five percent of the fully diluted company as of June 30 - to hold for the benefit mission (' + a(S1, 'the governance section') + '). The listed board around them is experienced: Reed Hastings, Christopher Liddell, Vas Narasimhan, Yasmin Razavi sit beside the two Amodeis.'),
 p(' Each guardrail answers a failure the founders watched from inside. The trust answers the board-coup failure mode - no investor can seize the lab by seizing its directors. The founder share answers the drift failure mode - no acquirer can outvote the mission. The benefit fund answers the capture failure mode - a slice of the upside is permanently bound to the stated purpose. Whether these are safeguards or simply a very elaborate way to say trust us is precisely what Wednesday\'s order book is a referendum on.'),
]})

G.append({'heading': '7. The pricing room', 'blocks': [
 p(' The terms are set. Anthropic is offering 825 million Class A shares - 801,351,354 from the company, 23,648,646 from selling stockholders whose proceeds the company will not touch - at a range of 70 to 78 dollars, with a 123.75-million-share greenshoe, listing on Nasdaq as ANT. At the range the raise is 57.75 to 64.35 billion dollars; the implied valuation runs to 1.404 trillion at the top (' + a(TC, 'TechCrunch\'s read of the range') + '). The book is reported about six times covered, Bloomberg has said - a report, not a company figure. At the top half of the range each of the seven co-founders would hold stock worth roughly 18 billion dollars (' + a(STKA, 'stockanalysis\'s math') + '). The whole sector is watching because the whole sector is implicated: the largest pure-AI listing ever attempted lands while the trade is still absorbing Nvidia\'s worst week since April and a chief-executive vacuum at its center (' + a(CNBC, 'CNBC\'s framing') + ').'),
 p(' On Wednesday the bookrunners will set a number. Around the book sit two kinds of conviction. The sellers are asking the market to price something that has never been priced: a company whose charter subordinates it to a mission, whose board answers to a trust, whose founders cannot be outvoted, and whose commitments run to nearly a trillion dollars against thirty-three billion of nine-month revenue. The buyers are deciding whether those two lists - the guardrails and the burn - are one fact or two: whether the discipline that built the constitution is the same discipline that makes the arithmetic survivable. The industry around that book grew up, professionally, in the shadow of the lab this one left. Dario Amodei walked out of OpenAI in December 2020 with six colleagues and a thesis about what a careful lab could become. On Thursday morning the ticker ANT is set to print its first price, and nearly six years of careful becomes a number with a market attached to it.'),
]})

d = json.load(open('editions-src/longreads.json'))
d['42'] = lr
json.dump(d, open('editions-src/longreads.json','w'), indent=1, ensure_ascii=False)
print('LR42 written:', sum(len(g['blocks']) for g in G), 'blocks,',
      sum(len(b['html'].split()) for g in G for b in g['blocks']), 'words')
